window.CHUJI_DATA_7 = [{"l": 361, "lt": "Lesson 61 The Hare and the Turtle 兔子与乌龟", "i": 1, "type": "reading", "en": "The hare can run very fast, but the turtle can only walk slowly.", "zh": "兔子可以跑得很快，但乌龟只能慢慢地走。", "audio": "chuji_l61_01.mp3", "localAudio": "audio_chunks/chuji_l61_01.mp3", "b64": "", "src": "chuji"}, {"l": 361, "lt": "Lesson 61 The Hare and the Turtle 兔子与乌龟", "i": 2, "type": "reading", "en": "One day the hare proudly challenged the turtle to a race.", "zh": "有一天兔子骄傲地向乌龟挑战赛跑。", "audio": "chuji_l61_02.mp3", "localAudio": "audio_chunks/chuji_l61_02.mp3", "b64": "", "src": "chuji"}, {"l": 361, "lt": "Lesson 61 The Hare and the Turtle 兔子与乌龟", "i": 3, "type": "reading", "en": "The hare started quickly but stopped to take a nap every now and then.", "zh": "兔子开始时跑得很快，但它偶尔会停下来小睡一下。", "audio": "chuji_l61_03.mp3", "localAudio": "audio_chunks/chuji_l61_03.mp3", "b64": "", "src": "chuji"}, {"l": 361, "lt": "Lesson 61 The Hare and the Turtle 兔子与乌龟", "i": 4, "type": "reading", "en": "The turtle walked slowly but surely.", "zh": "乌龟慢慢地走，却走得很稳健。", "audio": "chuji_l61_04.mp3", "localAudio": "audio_chunks/chuji_l61_04.mp3", "b64": "", "src": "chuji"}, {"l": 361, "lt": "Lesson 61 The Hare and the Turtle 兔子与乌龟", "i": 5, "type": "reading", "en": "While the hare was sleeping, the turtle passed him.", "zh": "趁兔子在睡觉时，乌龟走过了兔子。", "audio": "chuji_l61_05.mp3", "localAudio": "audio_chunks/chuji_l61_05.mp3", "b64": "", "src": "chuji"}, {"l": 361, "lt": "Lesson 61 The Hare and the Turtle 兔子与乌龟", "i": 6, "type": "reading", "en": "Finally, the turtle won the race.", "zh": "乌龟终于赢了比赛。", "audio": "chuji_l61_06.mp3", "localAudio": "audio_chunks/chuji_l61_06.mp3", "b64": "", "src": "chuji"}, {"l": 361, "lt": "Lesson 61 The Hare and the Turtle 兔子与乌龟", "i": 7, "type": "reading", "en": "In the end, he was rewarded for his perseverance.", "zh": "最后它因坚忍不拔的精神而获得回报。", "audio": "chuji_l61_07.mp3", "localAudio": "audio_chunks/chuji_l61_07.mp3", "b64": "", "src": "chuji"}, {"l": 361, "lt": "Lesson 61 The Hare and the Turtle 兔子与乌龟", "i": 8, "type": "reading", "en": "We can all learn a lesson from the turtle.", "zh": "我们全都可以从乌龟那里得到一个好的教训。", "audio": "chuji_l61_08.mp3", "localAudio": "audio_chunks/chuji_l61_08.mp3", "b64": "", "src": "chuji"}, {"l": 362, "lt": "Lesson 62 Practice Makes Perfect 熟能生巧", "i": 1, "type": "dialog", "en": "Can you help me gift-wrap this, please?", "zh": "请你帮我把这个东西用礼品纸包起来好吗？", "audio": "chuji_l62_01.mp3", "localAudio": "audio_chunks/chuji_l62_01.mp3", "b64": "", "src": "chuji", "speaker": "Customer", "note": "说话人: Customer"}, {"l": 362, "lt": "Lesson 62 Practice Makes Perfect 熟能生巧", "i": 2, "type": "dialog", "en": "Sure.", "zh": "好啊。", "audio": "chuji_l62_02.mp3", "localAudio": "audio_chunks/chuji_l62_02.mp3", "b64": "", "src": "chuji", "speaker": "Salesgirl", "note": "说话人: Salesgirl"}, {"l": 362, "lt": "Lesson 62 Practice Makes Perfect 熟能生巧", "i": 3, "type": "dialog", "en": "Wow! You did that beautifully.", "zh": "哇！你包得好美啊。", "audio": "chuji_l62_03.mp3", "localAudio": "audio_chunks/chuji_l62_03.mp3", "b64": "", "src": "chuji", "speaker": "Customer", "note": "说话人: Customer"}, {"l": 362, "lt": "Lesson 62 Practice Makes Perfect 熟能生巧", "i": 4, "type": "dialog", "en": "Well, I practice daily.", "zh": "嗯，我每天都在练习嘛。", "audio": "chuji_l62_04.mp3", "localAudio": "audio_chunks/chuji_l62_04.mp3", "b64": "", "src": "chuji", "speaker": "Salesgirl", "note": "说话人: Salesgirl"}, {"l": 362, "lt": "Lesson 62 Practice Makes Perfect 熟能生巧", "i": 5, "type": "dialog", "en": "Practice makes perfect, right?", "zh": "熟能生巧，对吗？", "audio": "chuji_l62_05.mp3", "localAudio": "audio_chunks/chuji_l62_05.mp3", "b64": "", "src": "chuji", "speaker": "Customer", "note": "说话人: Customer"}, {"l": 362, "lt": "Lesson 62 Practice Makes Perfect 熟能生巧", "i": 6, "type": "dialog", "en": "Certainly!", "zh": "那是当然的啰！", "audio": "chuji_l62_06.mp3", "localAudio": "audio_chunks/chuji_l62_06.mp3", "b64": "", "src": "chuji", "speaker": "Salesgirl", "note": "说话人: Salesgirl"}, {"l": 363, "lt": "Lesson 63 Saving a Drowning Boy 救难记", "i": 1, "type": "reading", "en": "Ray was walking on the beach one summer day when he heard a little boy shout, \"Help! Help!\"", "zh": "某个夏日雷正在海滩上散步，这时他听到一个小男孩大叫：“救命啊！救命啊！”", "audio": "chuji_l63_01.mp3", "localAudio": "audio_chunks/chuji_l63_01.mp3", "b64": "", "src": "chuji"}, {"l": 363, "lt": "Lesson 63 Saving a Drowning Boy 救难记", "i": 2, "type": "reading", "en": "The boy was drowning.", "zh": "这个男孩快要淹死了。", "audio": "chuji_l63_02.mp3", "localAudio": "audio_chunks/chuji_l63_02.mp3", "b64": "", "src": "chuji"}, {"l": 363, "lt": "Lesson 63 Saving a Drowning Boy 救难记", "i": 3, "type": "reading", "en": "Without thinking, Ray dove into the water.", "zh": "雷不加思索地就跳进了水里。", "audio": "chuji_l63_03.mp3", "localAudio": "audio_chunks/chuji_l63_03.mp3", "b64": "", "src": "chuji"}, {"l": 363, "lt": "Lesson 63 Saving a Drowning Boy 救难记", "i": 4, "type": "reading", "en": "Soon he was swimming back to shore with the boy.", "zh": "不久他便带着小男孩游回岸上。", "audio": "chuji_l63_04.mp3", "localAudio": "audio_chunks/chuji_l63_04.mp3", "b64": "", "src": "chuji"}, {"l": 363, "lt": "Lesson 63 Saving a Drowning Boy 救难记", "i": 5, "type": "reading", "en": "Crowds of people were watching eagerly.", "zh": "成群的人们正焦急地注视着。", "audio": "chuji_l63_05.mp3", "localAudio": "audio_chunks/chuji_l63_05.mp3", "b64": "", "src": "chuji"}, {"l": 363, "lt": "Lesson 63 Saving a Drowning Boy 救难记", "i": 6, "type": "reading", "en": "After a while the boy was breathing again.", "zh": "过了一会儿这个男孩又开始呼吸了。", "audio": "chuji_l63_06.mp3", "localAudio": "audio_chunks/chuji_l63_06.mp3", "b64": "", "src": "chuji"}, {"l": 363, "lt": "Lesson 63 Saving a Drowning Boy 救难记", "i": 7, "type": "reading", "en": "Then the boy sat up and said to Ray, \"You are my hero.\"", "zh": "接着这个男孩坐了起来，对雷说：“你是我的英雄。”", "audio": "chuji_l63_07.mp3", "localAudio": "audio_chunks/chuji_l63_07.mp3", "b64": "", "src": "chuji"}, {"l": 364, "lt": "Lesson 64 Dan's a Good Swimmer 丹很会游泳", "i": 1, "type": "dialog", "en": "Dan's a good swimmer, isn't he?", "zh": "丹很会游泳，是不是？", "audio": "chuji_l64_01.mp3", "localAudio": "audio_chunks/chuji_l64_01.mp3", "b64": "", "src": "chuji", "speaker": "Lucy", "note": "说话人: Lucy"}, {"l": 364, "lt": "Lesson 64 Dan's a Good Swimmer 丹很会游泳", "i": 2, "type": "dialog", "en": "Yes. In fact, he's a lifeguard.", "zh": "是啊。事实上，他是个救生员。", "audio": "chuji_l64_02.mp3", "localAudio": "audio_chunks/chuji_l64_02.mp3", "b64": "", "src": "chuji", "speaker": "Lewis", "note": "说话人: Lewis"}, {"l": 364, "lt": "Lesson 64 Dan's a Good Swimmer 丹很会游泳", "i": 3, "type": "dialog", "en": "Wow! Can he teach me the butterfly and the backstroke?", "zh": "哇！他能教我蝶泳和仰泳吗？", "audio": "chuji_l64_03.mp3", "localAudio": "audio_chunks/chuji_l64_03.mp3", "b64": "", "src": "chuji", "speaker": "Lucy", "note": "说话人: Lucy"}, {"l": 364, "lt": "Lesson 64 Dan's a Good Swimmer 丹很会游泳", "i": 4, "type": "dialog", "en": "Yes. He can also teach you the free style and the breaststroke.", "zh": "能。他还能教你自由式和蛙式。", "audio": "chuji_l64_04.mp3", "localAudio": "audio_chunks/chuji_l64_04.mp3", "b64": "", "src": "chuji", "speaker": "Lewis", "note": "说话人: Lewis"}, {"l": 364, "lt": "Lesson 64 Dan's a Good Swimmer 丹很会游泳", "i": 5, "type": "dialog", "en": "Great!", "zh": "太棒了！", "audio": "chuji_l64_05.mp3", "localAudio": "audio_chunks/chuji_l64_05.mp3", "b64": "", "src": "chuji", "speaker": "Lucy", "note": "说话人: Lucy"}, {"l": 365, "lt": "Lesson 65 The Fortune-teller 算命师", "i": 1, "type": "reading", "en": "My friend Mike is a fortune-teller.", "zh": "我的朋友迈克是个算命师。", "audio": "chuji_l65_01.mp3", "localAudio": "audio_chunks/chuji_l65_01.mp3", "b64": "", "src": "chuji"}, {"l": 365, "lt": "Lesson 65 The Fortune-teller 算命师", "i": 2, "type": "reading", "en": "He often tells me many things about my future.", "zh": "他经常会告诉我许多有关我前途的事。", "audio": "chuji_l65_02.mp3", "localAudio": "audio_chunks/chuji_l65_02.mp3", "b64": "", "src": "chuji"}, {"l": 365, "lt": "Lesson 65 The Fortune-teller 算命师", "i": 3, "type": "reading", "en": "First, I will become a father next year.", "zh": "首先，我明年就要当爸爸了。", "audio": "chuji_l65_03.mp3", "localAudio": "audio_chunks/chuji_l65_03.mp3", "b64": "", "src": "chuji"}, {"l": 365, "lt": "Lesson 65 The Fortune-teller 算命师", "i": 4, "type": "reading", "en": "Then, I will get a promotion and earn a lot of money.", "zh": "然后，我会获得提升并且挣大钱。", "audio": "chuji_l65_04.mp3", "localAudio": "audio_chunks/chuji_l65_04.mp3", "b64": "", "src": "chuji"}, {"l": 365, "lt": "Lesson 65 The Fortune-teller 算命师", "i": 5, "type": "reading", "en": "Two years later, I will buy a new car.", "zh": "两年后，我会买部新车。", "audio": "chuji_l65_05.mp3", "localAudio": "audio_chunks/chuji_l65_05.mp3", "b64": "", "src": "chuji"}, {"l": 365, "lt": "Lesson 65 The Fortune-teller 算命师", "i": 6, "type": "reading", "en": "Soon after that, I will be able to afford a new house.", "zh": "之后没多久，我就会有能力买幢新房子。", "audio": "chuji_l65_06.mp3", "localAudio": "audio_chunks/chuji_l65_06.mp3", "b64": "", "src": "chuji"}, {"l": 365, "lt": "Lesson 65 The Fortune-teller 算命师", "i": 7, "type": "reading", "en": "I'm not superstitious, but I hope he's right.", "zh": "我并不迷信，但我希望他说的是真的。", "audio": "chuji_l65_07.mp3", "localAudio": "audio_chunks/chuji_l65_07.mp3", "b64": "", "src": "chuji"}, {"l": 366, "lt": "Lesson 66 Will It Leave on Time? 它会准时开吗？", "i": 1, "type": "dialog", "en": "Excuse me. When will the next train leave?", "zh": "对不起，请问下一班火车何时开？", "audio": "chuji_l66_01.mp3", "localAudio": "audio_chunks/chuji_l66_01.mp3", "b64": "", "src": "chuji", "speaker": "Girl", "note": "说话人: Girl"}, {"l": 366, "lt": "Lesson 66 Will It Leave on Time? 它会准时开吗？", "i": 2, "type": "dialog", "en": "In ten minutes.", "zh": "十分钟后。", "audio": "chuji_l66_02.mp3", "localAudio": "audio_chunks/chuji_l66_02.mp3", "b64": "", "src": "chuji", "speaker": "Man", "note": "说话人: Man"}, {"l": 366, "lt": "Lesson 66 Will It Leave on Time? 它会准时开吗？", "i": 3, "type": "dialog", "en": "Will it leave on time?", "zh": "它会准时开吗？", "audio": "chuji_l66_03.mp3", "localAudio": "audio_chunks/chuji_l66_03.mp3", "b64": "", "src": "chuji", "speaker": "Girl", "note": "说话人: Girl"}, {"l": 366, "lt": "Lesson 66 Will It Leave on Time? 它会准时开吗？", "i": 4, "type": "dialog", "en": "It always does.", "zh": "它总是很准时的。", "audio": "chuji_l66_04.mp3", "localAudio": "audio_chunks/chuji_l66_04.mp3", "b64": "", "src": "chuji", "speaker": "Man", "note": "说话人: Man"}, {"l": 366, "lt": "Lesson 66 Will It Leave on Time? 它会准时开吗？", "i": 5, "type": "dialog", "en": "Thank you.", "zh": "谢谢你。", "audio": "chuji_l66_05.mp3", "localAudio": "audio_chunks/chuji_l66_05.mp3", "b64": "", "src": "chuji", "speaker": "Girl", "note": "说话人: Girl"}, {"l": 367, "lt": "Lesson 67 Getting Married 结婚", "i": 1, "type": "reading", "en": "My girlfriend and I are going to get married this year.", "zh": "我和女友今年将结婚。", "audio": "chuji_l67_01.mp3", "localAudio": "audio_chunks/chuji_l67_01.mp3", "b64": "", "src": "chuji"}, {"l": 367, "lt": "Lesson 67 Getting Married 结婚", "i": 2, "type": "reading", "en": "We are going to have a big wedding party.", "zh": "我们将举行盛大的婚宴。", "audio": "chuji_l67_02.mp3", "localAudio": "audio_chunks/chuji_l67_02.mp3", "b64": "", "src": "chuji"}, {"l": 367, "lt": "Lesson 67 Getting Married 结婚", "i": 3, "type": "reading", "en": "All our friends and relatives are going to come.", "zh": "我们所有的亲朋好友都会来参加。", "audio": "chuji_l67_03.mp3", "localAudio": "audio_chunks/chuji_l67_03.mp3", "b64": "", "src": "chuji"}, {"l": 367, "lt": "Lesson 67 Getting Married 结婚", "i": 4, "type": "reading", "en": "We are going to have a traditional wedding.", "zh": "我们将要举行传统的婚礼。", "audio": "chuji_l67_04.mp3", "localAudio": "audio_chunks/chuji_l67_04.mp3", "b64": "", "src": "chuji"}, {"l": 367, "lt": "Lesson 67 Getting Married 结婚", "i": 5, "type": "reading", "en": "After the wedding we are going to live with my parents.", "zh": "婚礼后我们要和我的父母亲一起住。", "audio": "chuji_l67_05.mp3", "localAudio": "audio_chunks/chuji_l67_05.mp3", "b64": "", "src": "chuji"}, {"l": 367, "lt": "Lesson 67 Getting Married 结婚", "i": 6, "type": "reading", "en": "We are going to be one big happy family.", "zh": "我们将成为一个快乐的大家庭。", "audio": "chuji_l67_06.mp3", "localAudio": "audio_chunks/chuji_l67_06.mp3", "b64": "", "src": "chuji"}, {"l": 368, "lt": "Lesson 68 Are You Going to Come? 你会来吗？", "i": 1, "type": "dialog", "en": "Are you going to come to my wedding?", "zh": "你会来参加我的婚礼吗？", "audio": "chuji_l68_01.mp3", "localAudio": "audio_chunks/chuji_l68_01.mp3", "b64": "", "src": "chuji", "speaker": "Candy", "note": "说话人: Candy"}, {"l": 368, "lt": "Lesson 68 Are You Going to Come? 你会来吗？", "i": 2, "type": "dialog", "en": "Of course.", "zh": "当然会。", "audio": "chuji_l68_02.mp3", "localAudio": "audio_chunks/chuji_l68_02.mp3", "b64": "", "src": "chuji", "speaker": "Joe", "note": "说话人: Joe"}, {"l": 368, "lt": "Lesson 68 Are You Going to Come? 你会来吗？", "i": 3, "type": "dialog", "en": "Good. Are you going to bring your girlfriend?", "zh": "太好了。你会带你女朋友一起来吗？", "audio": "chuji_l68_03.mp3", "localAudio": "audio_chunks/chuji_l68_03.mp3", "b64": "", "src": "chuji", "speaker": "Candy", "note": "说话人: Candy"}, {"l": 368, "lt": "Lesson 68 Are You Going to Come? 你会来吗？", "i": 4, "type": "dialog", "en": "Yes. She likes weddings.", "zh": "会。她很喜欢参加婚礼。", "audio": "chuji_l68_04.mp3", "localAudio": "audio_chunks/chuji_l68_04.mp3", "b64": "", "src": "chuji", "speaker": "Joe", "note": "说话人: Joe"}, {"l": 368, "lt": "Lesson 68 Are You Going to Come? 你会来吗？", "i": 5, "type": "dialog", "en": "So when are you going to get married?", "zh": "那么你们什么时候结婚呢？", "audio": "chuji_l68_05.mp3", "localAudio": "audio_chunks/chuji_l68_05.mp3", "b64": "", "src": "chuji", "speaker": "Candy", "note": "说话人: Candy"}, {"l": 368, "lt": "Lesson 68 Are You Going to Come? 你会来吗？", "i": 6, "type": "dialog", "en": "We haven't decided yet.", "zh": "我们尚未决定。", "audio": "chuji_l68_06.mp3", "localAudio": "audio_chunks/chuji_l68_06.mp3", "b64": "", "src": "chuji", "speaker": "Joe", "note": "说话人: Joe"}, {"l": 369, "lt": "Lesson 69 Running a Bookstore 经营书店", "i": 1, "type": "reading", "en": "Tom will be retiring next year.", "zh": "汤姆明年就要退休了。", "audio": "chuji_l69_01.mp3", "localAudio": "audio_chunks/chuji_l69_01.mp3", "b64": "", "src": "chuji"}, {"l": 369, "lt": "Lesson 69 Running a Bookstore 经营书店", "i": 2, "type": "reading", "en": "He will be opening a small bookstore.", "zh": "他将开一家小书店。", "audio": "chuji_l69_02.mp3", "localAudio": "audio_chunks/chuji_l69_02.mp3", "b64": "", "src": "chuji"}, {"l": 369, "lt": "Lesson 69 Running a Bookstore 经营书店", "i": 3, "type": "reading", "en": "His wife will be helping him run the store.", "zh": "他的太太会帮他经营这家店。", "audio": "chuji_l69_03.mp3", "localAudio": "audio_chunks/chuji_l69_03.mp3", "b64": "", "src": "chuji"}, {"l": 369, "lt": "Lesson 69 Running a Bookstore 经营书店", "i": 4, "type": "reading", "en": "It will be a small family business, so they won't be needing too much money.", "zh": "这将是一个小型的家庭事业，所以他们并不需要太多资金。", "audio": "chuji_l69_04.mp3", "localAudio": "audio_chunks/chuji_l69_04.mp3", "b64": "", "src": "chuji"}, {"l": 369, "lt": "Lesson 69 Running a Bookstore 经营书店", "i": 5, "type": "reading", "en": "He won't be making a lot of money, but it'll be enough.", "zh": "他将不会挣很多钱，但那样就够用了。", "audio": "chuji_l69_05.mp3", "localAudio": "audio_chunks/chuji_l69_05.mp3", "b64": "", "src": "chuji"}, {"l": 370, "lt": "Lesson 70 When Will You Be Moving? 你什么时候搬家？", "i": 1, "type": "dialog", "en": "When will you be moving?", "zh": "你什么时候搬家？", "audio": "chuji_l70_01.mp3", "localAudio": "audio_chunks/chuji_l70_01.mp3", "b64": "", "src": "chuji", "speaker": "Tina", "note": "说话人: Tina"}, {"l": 370, "lt": "Lesson 70 When Will You Be Moving? 你什么时候搬家？", "i": 2, "type": "dialog", "en": "Next week.", "zh": "下星期。", "audio": "chuji_l70_02.mp3", "localAudio": "audio_chunks/chuji_l70_02.mp3", "b64": "", "src": "chuji", "speaker": "Chuck", "note": "说话人: Chuck"}, {"l": 370, "lt": "Lesson 70 When Will You Be Moving? 你什么时候搬家？", "i": 3, "type": "dialog", "en": "When will we be seeing you again?", "zh": "我们什么时候会再见到你呢？", "audio": "chuji_l70_03.mp3", "localAudio": "audio_chunks/chuji_l70_03.mp3", "b64": "", "src": "chuji", "speaker": "Tina", "note": "说话人: Tina"}, {"l": 370, "lt": "Lesson 70 When Will You Be Moving? 你什么时候搬家？", "i": 4, "type": "dialog", "en": "Maybe next year.", "zh": "也许明年吧。", "audio": "chuji_l70_04.mp3", "localAudio": "audio_chunks/chuji_l70_04.mp3", "b64": "", "src": "chuji", "speaker": "Chuck", "note": "说话人: Chuck"}, {"l": 370, "lt": "Lesson 70 When Will You Be Moving? 你什么时候搬家？", "i": 5, "type": "dialog", "en": "Don't forget to write.", "zh": "别忘了写信啊。", "audio": "chuji_l70_05.mp3", "localAudio": "audio_chunks/chuji_l70_05.mp3", "b64": "", "src": "chuji", "speaker": "Tina", "note": "说话人: Tina"}, {"l": 370, "lt": "Lesson 70 When Will You Be Moving? 你什么时候搬家？", "i": 6, "type": "dialog", "en": "I won't. Goodbye, Tina.", "zh": "我不会忘记的。再见了，蒂娜。", "audio": "chuji_l70_06.mp3", "localAudio": "audio_chunks/chuji_l70_06.mp3", "b64": "", "src": "chuji", "speaker": "Chuck", "note": "说话人: Chuck"}];